 10→func TestParseHookEvent_SessionStart(t *testing.T) {
 11→	t.Parallel()
 12→
 13→	ag := &CopilotAgent{}
 14→	// Actual Copilot sessionStart stdin format (no sessionId/transcriptPath)
 15→	input := `{"timestamp":1771465283476,"cwd":"/Users/test/project","source":"new","initialPrompt":"hello"}`
 16→
 17→	event, err := ag.ParseHookEvent(HookNameSessionStart, strings.NewReader(input))
 18→
 19→	if err != nil {
 20→		t.Fatalf("unexpected error: %v", err)
 21→	}
 22→	if event == nil {
 23→		t.Fatal("expected event, got nil")
 24→	}
 25→	if event.Type != agent.SessionStart {
 26→		t.Errorf("expected event type %v, got %v", agent.SessionStart, event.Type)
 27→	}
 28→	// sessionStart does NOT provide sessionId or transcriptPath
 29→	if event.SessionID != "" {
 30→		t.Errorf("expected empty session_id, got %q", event.SessionID)
 31→	}
 32→	if event.SessionRef != "" {
 33→		t.Errorf("expected empty session_ref, got %q", event.SessionRef)
 34→	}
 35→	if event.Timestamp.IsZero() {
 36→		t.Error("expected non-zero timestamp")
 37→	}
 38→}
