// parseSessionStart handles the sessionStart hook.
// Copilot's sessionStart stdin does NOT include sessionId or transcriptPath,
// so we return nil (no lifecycle action). The session is initialized later
// when agentStop fires with the actual sessionId.
func (c *CopilotAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	_, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
	if err != nil {
		return nil, err
	}
	return nil, nil //nolint:nilnil // nil event = no lifecycle action (no sessionId available)
}

// parseTurnStart handles the userPromptSubmitted hook.
// Copilot's userPromptSubmitted stdin does NOT include sessionId or transcriptPath,
// so we return nil (no lifecycle action). The lifecycle dispatcher requires sessionId
// for TurnStart to capture pre-prompt state and initialize the session, but copilot
// only provides this in agentStop. The prompt text is recovered from the transcript
// during TurnEnd processing.
func (c *CopilotAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	_, err := agent.ReadAndParseHookInput[userPromptRaw](stdin)
	if err != nil {
		return nil, err
	}
	return nil, nil //nolint:nilnil // nil event = no lifecycle action (no sessionId available)
}

